    SELECT
        'PROC'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(RECRUIT_PROCESS_NO), LENGTH('PROC' ) + 1)), 0) + 1, 6, '0')
    FROM RECRUIT_PROCESS

	INSERT INTO RECRUIT_PROCESS (
		RECRUIT_PROCESS_NO
		, RECRUITMENT_NO
		, COMPANY_NAME
		, RECRUIT_PROCESS_STEP
		, RECRUIT_PROCESS_FINAL
		, RECRUIT_PROCESS_TYPE
	) VALUES (
		#{recruitProcessNo}
		, #{recruitmentNo}
		, #{companyName}
		, #{recruitProcessStep}
		, #{recruitProcessFinal}
		, #{recruitProcessType}
	)

