	RECRUITMENT_NO = #{recruitmentNo}
	, COMPANY_NAME = #{companyName}
	, RECRUIT_PROCESS_STEP = #{recruitProcessStep}
	, RECRUIT_PROCESS_FINAL = #{recruitProcessFinal}
	, RECRUIT_PROCESS_TYPE = #{recruitProcessType} 
WHERE RECRUIT_PROCESS_NO = #{recruitProcessNo}

